BEGIN;
INSERT INTO "CommonCodeGroup" (key,"nameKo","nameEn",description,"updatedAt") VALUES ('PROJECT_ORIGIN','프로젝트 작업 구분','Project origin','프로젝트를 수행한 배경: 개인, 교육, 회사',now()),('PROJECT_TYPE','프로젝트 유형','Project type','서비스 형태: 미지정, 웹, 하이브리드 앱',now()),('POST_CATEGORY','게시글 카테고리','Post category','게시글 주제 분류. 전체는 조회 조건이므로 코드로 저장하지 않음',now()) ON CONFLICT (key) DO UPDATE SET "nameKo"=EXCLUDED."nameKo","nameEn"=EXCLUDED."nameEn",description=EXCLUDED.description,"updatedAt"=now();
UPDATE "CommonCode" SET code='BUG_REPORT',"updatedAt"=now() WHERE "groupKey"='INQUIRY_TYPE' AND code='0';
UPDATE "CommonCode" SET code='GENERAL',"updatedAt"=now() WHERE "groupKey"='INQUIRY_TYPE' AND code='1';
UPDATE "CommonCode" SET code='PENDING',"updatedAt"=now() WHERE "groupKey"='INQUIRY_STATUS' AND code='0';
UPDATE "CommonCode" SET code='RECEIVED',"updatedAt"=now() WHERE "groupKey"='INQUIRY_STATUS' AND code='1';
UPDATE "CommonCode" SET code='IN_PROGRESS',"updatedAt"=now() WHERE "groupKey"='INQUIRY_STATUS' AND code='2';
UPDATE "CommonCode" SET code='PERSONAL',"updatedAt"=now() WHERE "groupKey"='PROJECT_ORIGIN' AND code='personal';
UPDATE "CommonCode" SET code='EDUCATION',"updatedAt"=now() WHERE "groupKey"='PROJECT_ORIGIN' AND code='education';
UPDATE "CommonCode" SET code='COMPANY',"updatedAt"=now() WHERE "groupKey"='PROJECT_ORIGIN' AND code='company';
UPDATE "CommonCode" SET code='WEB',"updatedAt"=now() WHERE "groupKey"='PROJECT_TYPE' AND code='website';
UPDATE "CommonCode" SET code='HYBRID_APP',"updatedAt"=now() WHERE "groupKey"='PROJECT_TYPE' AND code='hybrid_app';
INSERT INTO "CommonCode" ("groupKey",code,"nameKo","nameEn",position,"updatedAt") VALUES ('INQUIRY_TYPE','BUG_REPORT','버그 제보','Bug report',10,now()),('INQUIRY_TYPE','GENERAL','일반 문의','General inquiry',20,now()),('INQUIRY_STATUS','PENDING','대기','Pending',10,now()),('INQUIRY_STATUS','RECEIVED','접수','Received',20,now()),('INQUIRY_STATUS','IN_PROGRESS','처리 중','In progress',30,now()),('INQUIRY_STATUS','RESOLVED','처리 완료','Resolved',40,now()),('INQUIRY_STATUS','CLOSED','종료','Closed',50,now()),('PROJECT_ORIGIN','PERSONAL','개인','Personal',10,now()),('PROJECT_ORIGIN','EDUCATION','교육','Education',20,now()),('PROJECT_ORIGIN','COMPANY','회사','Company',30,now()),('PROJECT_TYPE','UNSPECIFIED','미지정','Unspecified',10,now()),('PROJECT_TYPE','WEB','웹','Web',20,now()),('PROJECT_TYPE','HYBRID_APP','하이브리드 앱','Hybrid app',30,now()),('POST_CATEGORY','NOTICE','공지사항','Notice',10,now()),('POST_CATEGORY','DEV_LOG','개발일지','Development',20,now()),('POST_CATEGORY','AI','AI 정보','AI',30,now()),('POST_CATEGORY','TECH','IT·기술','Technology',40,now()),('POST_CATEGORY','ISSUE','실시간 이슈','Current issues',50,now()),('POST_CATEGORY','ENTERTAINMENT','연예·문화','Entertainment & culture',60,now()),('POST_CATEGORY','CAREER','채용·커리어','Careers',70,now()),('POST_CATEGORY','FINANCE','주식·금융','Finance',80,now()),('POST_CATEGORY','REAL_ESTATE','부동산','Real estate',90,now()),('POST_CATEGORY','TROUBLESHOOTING','장애·이슈 해결','Troubleshooting',100,now()),('POST_CATEGORY','OTHER','기타','Other',110,now()) ON CONFLICT ("groupKey",code) DO UPDATE SET "nameKo"=EXCLUDED."nameKo","nameEn"=EXCLUDED."nameEn",position=EXCLUDED.position,"updatedAt"=now();
ALTER TABLE "Inquiry" ALTER COLUMN "statusCode" SET DEFAULT 'PENDING';
UPDATE "Project" SET "typeCode"='UNSPECIFIED' WHERE "typeCode" IS NULL;
ALTER TABLE "Project" ALTER COLUMN "typeCode" SET DEFAULT 'UNSPECIFIED';
UPDATE "Post" SET category='DEV_LOG' WHERE category='개발 기록';
UPDATE "Post" SET category='DEV_LOG' WHERE category='개발일지';
UPDATE "Post" SET category='AI' WHERE category='AI 정보';
UPDATE "Post" SET category='ENTERTAINMENT' WHERE category='연예 이슈';
UPDATE "Post" SET category='CAREER' WHERE category='채용·공채';
UPDATE "Post" SET category='FINANCE' WHERE category='주식·코인';
UPDATE "Post" SET category='REAL_ESTATE' WHERE category='부동산';
ALTER TABLE "Post" ADD COLUMN "categoryGroup" VARCHAR(60) NOT NULL DEFAULT 'POST_CATEGORY' CHECK ("categoryGroup"='POST_CATEGORY');
ALTER TABLE "Post" ADD CONSTRAINT "Post_categoryGroup_category_fkey" FOREIGN KEY ("categoryGroup",category) REFERENCES "CommonCode"("groupKey",code) ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE INDEX "Post_categoryGroup_category_idx" ON "Post"("categoryGroup",category);
COMMIT;
